// Global Objects
SqlConnection dbConn = null;
SqlTransaction dbTran = null;

Success = true;
Error_Message = "";

// Check the status of the connection to ensure it hasn't been opened already.
if ((dbConn == null) || ((dbConn.State == ConnectionState.Closed) || (dbConn.State == ConnectionState.Broken)))
{		
	try
	{
		// If the connection state is 'Broken', we need to close it before re-opening it.
		if ((dbConn != null) && (dbConn.State == ConnectionState.Broken))
			dbConn.Close();

		// Attempt to open the SQL Server connection.
		dbConn = new SqlConnection(Connection_String);
		dbConn.Open();
	} 
	catch (Exception ex)
	{
		Success = false;
		Error_Message = ex.Message;
	}
}

try
{
	if (dbConn != null)
	{
		dbConn.Close();
		dbConn.Dispose();
	}
}
finally
{
	dbConn = null;
}

isOpen = false;

if ((dbConn != null) && (dbConn.State == ConnectionState.Open))
	isOpen = true;

// Assume success.
Success = true;
Error_Message = "";

try
{
	dbTran = dbConn.BeginTransaction();
}
catch (Exception ex)
{
	Success = false;
	Error_Message = ex.Message;
}

// Assume success
Success = true;
Error_Message = "";

try
{
	dbTran.Commit();
	dbTran.Dispose();
	dbTran = null;
}
catch (Exception ex)
{
	Success = false;
	Error_Message = ex.Message;
}

// Assume success
Success = true;
Error_Message = "";

try
{
	dbTran.Rollback();
	dbTran.Dispose();
	dbTran = null;
}
catch (Exception ex)
{
	Success = false;
	Error_Message = ex.Message;
}

// Assume success.
Success = true;
Error_Message = "";
Records_Affected = 0;

try
{
	using (SqlCommand cmd = new SqlCommand())
	{
		cmd.Connection = dbConn;
		cmd.CommandText = SQL;
		cmd.Transaction = dbTran; // If we're not using a manual transaction, this statement will do nothing.
		cmd.CommandTimeout = (int)CommandTimeout;
		Records_Affected = cmd.ExecuteNonQuery();
	}
}
catch (Exception ex)
{
	Success = false;
	Error_Message = ex.Message;
}

// Assume success.
Success = true;
Error_Message = "";
Number_Result = 0;

try
{
	using (SqlCommand cmd = new SqlCommand())
	{
		cmd.Connection = dbConn;
		cmd.CommandText = SQL;
		cmd.Transaction = dbTran; // If we're not using a manual transaction, this statement will do nothing.
		cmd.CommandTimeout = (int)CommandTimeout;
		Number_Result = (decimal)cmd.ExecuteScalar();
	}
}
catch (Exception ex)
{
	Success = false;
	Error_Message = ex.Message;
}

// Assume success.
Success = true;
Error_Message = "";
Text_Result = "";

try
{
	using (SqlCommand cmd = new SqlCommand())
	{
		cmd.Connection = dbConn;
		cmd.CommandText = SQL;
		cmd.Transaction = dbTran; // If we're not using a manual transaction, this statement will do nothing.
		cmd.CommandTimeout = (int)CommandTimeout;
		Text_Result = cmd.ExecuteScalar().ToString();
	}
}
catch (Exception ex)
{
	Success = false;
	Error_Message = ex.Message;
}

// Assume success.
Success = true;
Error_Message = "";
Results = null;

try
{
	using (SqlCommand cmd = new SqlCommand())
	{
		cmd.Connection = dbConn;
		cmd.CommandText = SQL;
		cmd.Transaction = dbTran; // If we're not using a manual transaction, this statement will do nothing.
		cmd.CommandTimeout = (int)CommandTimeout;

		using (SqlDataAdapter adapter = new SqlDataAdapter())
		{
			adapter.SelectCommand = cmd;
			DataSet ds = new DataSet();
			adapter.Fill(ds);
			Results = ds.Tables[0];
		}
	}
}
catch (Exception ex)
{
	Success = false;
	Error_Message = ex.Message;
}

Success = true;
Error_Message = "";
Records_Affected = 0;

try
{
    if (Data_Collection == null || Data_Collection.Columns.Count == 0)
        return;

    if (string.IsNullOrWhiteSpace(Table_Name) || !System.Text.RegularExpressions.Regex.IsMatch(Table_Name, @"^[A-Za-z_][A-Za-z0-9_]*$"))
        throw new ArgumentException("Invalid SQL Server table name.");

    string safeTable = "[dbo].[" + Table_Name + "]";
    string objectName = "dbo." + Table_Name;
    System.Collections.Generic.List<string> colDefs = new System.Collections.Generic.List<string>();
    System.Collections.Generic.List<string> colNames = new System.Collections.Generic.List<string>();
    System.Collections.Generic.List<string> paramNames = new System.Collections.Generic.List<string>();

    for (int i = 0; i < Data_Collection.Columns.Count; i++)
    {
        string cName = Data_Collection.Columns[i].ColumnName.Trim();
        if (string.IsNullOrEmpty(cName)) cName = "Col" + (i + 1).ToString();
        string quotedName = "[" + cName.Replace("]", "]]" ) + "]";
        colDefs.Add(quotedName + " NVARCHAR(4000) NULL");
        colNames.Add(quotedName);
        paramNames.Add("@p" + i.ToString());
    }

    using (SqlTransaction tran = dbConn.BeginTransaction())
    {
        using (SqlCommand cmd = new SqlCommand())
        {
            cmd.Connection = dbConn;
            cmd.Transaction = tran;
            if (Clear_First)
            {
                cmd.CommandText = "IF OBJECT_ID(N'" + objectName + "', N'U') IS NOT NULL DROP TABLE " + safeTable + ";";
                cmd.ExecuteNonQuery();
            }
            cmd.CommandText = "IF OBJECT_ID(N'" + objectName + "', N'U') IS NULL CREATE TABLE " + safeTable + " (" + string.Join(", ", colDefs.ToArray()) + ");";
            cmd.ExecuteNonQuery();

            cmd.CommandText = "INSERT INTO " + safeTable + " (" + string.Join(", ", colNames.ToArray()) + ") VALUES (" + string.Join(", ", paramNames.ToArray()) + ");";
            for (int i = 0; i < Data_Collection.Columns.Count; i++)
                cmd.Parameters.Add(new SqlParameter("@p" + i.ToString(), SqlDbType.NVarChar, 4000));

            foreach (DataRow row in Data_Collection.Rows)
            {
                for (int i = 0; i < Data_Collection.Columns.Count; i++)
                {
                    object val = row[i];
                    cmd.Parameters[i].Value = (val == null || val == DBNull.Value) ? (object)DBNull.Value : val.ToString();
                }
                Records_Affected += cmd.ExecuteNonQuery();
            }
        }
        tran.Commit();
    }
}
catch (Exception ex)
{
    Success = false;
    Error_Message = ex.Message;
}
